export function DoubleFlush({onCommit}:{onCommit:(text:string)=>void}){
  const [n,setN]=useState(0);
  return <button type="button" onClick={e=>{
    const button=e.currentTarget;
    flushSync(()=>setN(x=>x+1));onCommit(button.textContent??"");
    flushSync(()=>setN(x=>x+1));onCommit(button.textContent??"");
  }}>{n}</button>;
}

